// Languages: the game is written in English, and tr() turns any line into Dutch when Nederlands is picked.
// Lookup order: the exact line, then the line with its numbers swapped for #, then a few patterns with names in them.
const KEY = 'renas-rocket-rumble-lang';
let saved = null;
try { saved = localStorage.getItem(KEY); } catch (e) { /* private mode */ }
export const LANG = { cur: saved || ((navigator.language || '').toLowerCase().startsWith('nl') ? 'nl' : 'en') };
const listeners = [];
export function onLang(fn) { listeners.push(fn); }
export function setLang(l) {
  LANG.cur = l;
  try { localStorage.setItem(KEY, l); } catch (e) { /* ignore */ }
  applyHTML();
  listeners.forEach((fn) => fn(l));
}
// static HTML: elements carry their Dutch text in data-nl; the English text is remembered the first time
export function applyHTML() {
  document.documentElement.lang = LANG.cur;
  for (const el of document.querySelectorAll('[data-nl]')) {
    if (el.dataset.en === undefined) el.dataset.en = el.innerHTML;
    el.innerHTML = LANG.cur === 'nl' ? el.dataset.nl : el.dataset.en;
  }
}
const and = (s) => s.replace(/ and /g, ' en ');
const RULES = [
  [/^<kbd>E<\/kbd> talk to (.+)$/, (n) => `<kbd>E</kbd> praat met ${n}`],
  [/^<kbd>E<\/kbd> (.+)$/, (r) => `<kbd>E</kbd> ${tr(r)}`],
  [/^🔒 (.+)$/, (r) => `🔒 ${tr(r)}`],
  [/^Find (.+) and talk with E$/, (n) => `Zoek ${n} en praat met E`],
  [/^Bring it to (.+)$/, (n) => `Breng het naar ${n}`],
  [/^And (.+) up north needs help too\. That’s one more star shard\.$/, (n) => `En ${n} in het noorden heeft ook hulp nodig. Dat is nog een sterrenscherf.`],
  [/^All five vinyls, ¡qué bueno! But the Launch Star still needs its star shards\. Go help (.+)\. Look for the yellow “!”\.$/,
    (n) => `Alle vijf de vinyls, ¡qué bueno! Maar de Launch Star heeft nog sterrenscherven nodig. Help ${and(n)} nog even. Zoek het gele “!”.`],
  [/^Five lanterns! Bright! But the Launch Star is still hungry for star shards\. (.+) still needs? your help\. Look for the yellow “!”\.$/,
    (n) => `Vijf lantaarns! Wat licht! Maar de Launch Star heeft nog honger naar sterrenscherven. ${and(n)} ${n.includes(' and ') ? 'hebben' : 'heeft'} je hulp nog nodig. Zoek het gele “!”.`],
  [/^All five lucky balls! But home plate still needs star shards\. (.+) still needs? you\. Look for the yellow “!”\. \*sniff\*$/,
    (n) => `Alle vijf de geluksballen! Maar de thuisplaat heeft nog sterrenscherven nodig. ${and(n)} ${n.includes(' and ') ? 'hebben' : 'heeft'} je nog nodig. Zoek het gele “!”. *snuf*`],
  [/^All five crystals\. Splendid\. But the Launch Star still wants its star shards\. (.+) still needs? you\. Look for the yellow “!”\.$/,
    (n) => `Alle vijf de kristallen. Voortreffelijk. Maar de Launch Star wil nog zijn sterrenscherven. ${and(n)} ${n.includes(' and ') ? 'hebben' : 'heeft'} je nog nodig. Zoek het gele “!”.`],
  [/^All five lucky stones! Grand! But the Launch Star still needs star shards\. (.+) still needs? you\. Look for the yellow “!”\.$/,
    (n) => `Alle vijf de geluksstenen! Top! Maar de Launch Star heeft nog sterrenscherven nodig. ${and(n)} ${n.includes(' and ') ? 'hebben' : 'heeft'} je nog nodig. Zoek het gele “!”.`],
  [/^All five golden bananas! AA AA! But the Launch Star still needs star shards\. (.+) still needs? your help\. Look for the yellow “!”\.$/,
    (n) => `Alle vijf de gouden bananen! AA AA! Maar de Launch Star heeft nog sterrenscherven nodig. ${and(n)} ${n.includes(' and ') ? 'hebben' : 'heeft'} je hulp nog nodig. Zoek het gele “!”.`],
  [/^All five fire gems! Hat-trick! But the Launch Star still needs star shards\. (.+) still needs? you\. Look for the yellow “!”\.$/,
    (n) => `Alle vijf de vuuredelstenen! Hattrick! Maar de Launch Star heeft nog sterrenscherven nodig. ${and(n)} ${n.includes(' and ') ? 'hebben' : 'heeft'} je nog nodig. Zoek het gele “!”.`],
  [/^All five golden scarabs! Wonderful! But the Launch Star still needs star shards\. (.+) still needs? you\. Look for the yellow “!”\.$/,
    (n) => `Alle vijf de gouden scarabeeën! Prachtig! Maar de Launch Star heeft nog sterrenscherven nodig. ${and(n)} ${n.includes(' and ') ? 'hebben' : 'heeft'} je nog nodig. Zoek het gele “!”.`],
  [/^All five power cells! Yes! But the Launch Star still needs star shards\. (.+) still needs? you\. Look for the yellow “!”\.$/,
    (n) => `Alle vijf de energiecellen! Yes! Maar de Launch Star heeft nog sterrenscherven nodig. ${and(n)} ${n.includes(' and ') ? 'hebben' : 'heeft'} je nog nodig. Zoek het gele “!”.`],
  [/^All five pearls! Blub blub! But the Launch Star still needs star shards\. (.+) still needs? you\. Look for the yellow “!”\.$/,
    (n) => `Alle vijf de parels! Blub blub! Maar de Launch Star heeft nog sterrenscherven nodig. ${and(n)} ${n.includes(' and ') ? 'hebben' : 'heeft'} je nog nodig. Zoek het gele “!”.`],
  [/^All five candles! Boo-tiful! But the Launch Star still needs star shards\. (.+) still needs? you\. Look for the yellow “!”\.$/,
    (n) => `Alle vijf de kaarsen! Boe-tiful! Maar de Launch Star heeft nog sterrenscherven nodig. ${and(n)} ${n.includes(' and ') ? 'hebben' : 'heeft'} je nog nodig. Zoek het gele “!”.`],
  [/^All five blueprints! You’re a legend, Binas! But the Launch Star still needs star shards\. (.+) still needs? you\. Look for the yellow “!”\.$/,
    (n) => `Alle vijf de bouwtekeningen! Je bent een legende, Binas! Maar de Launch Star heeft nog sterrenscherven nodig. ${and(n)} ${n.includes(' and ') ? 'hebben' : 'heeft'} je nog nodig. Zoek het gele “!”.`],
];
export function tr(s) {
  if (LANG.cur !== 'nl' || !s || typeof s !== 'string') return s;
  if (NL[s] !== undefined) return NL[s];
  const nums = [];
  const k = s.replace(/\d+/g, (m) => { nums.push(m); return '#'; });
  if (nums.length && NL[k] !== undefined) { let i = 0; return NL[k].replace(/#/g, () => nums[i++] ?? '#'); }
  for (const [re, fn] of RULES) { const m = s.match(re); if (m) return fn(...m.slice(1)); }
  return s;
}

